P = {}
P['papa-klemens-1'] = dict(name='Pope Clement I', cat='Early Church · Saint', born='Rome',
 bio='One of the first popes to lead the Church of Rome straight after the apostles. Tradition says he knew Peter and learned from him.',
 secs=[['His life', 'Very little is known about his life. Early sources remember him as a leading elder of the Roman community who had known Peter and Paul. Tradition says he died a martyr.'],
       ['The letter to the Corinthians', 'His letter to the Church in Corinth, written around the year 96, is one of the oldest Christian texts outside the New Testament. When the leaders of the Corinthian community were unjustly removed, this letter from Rome called them back to peace and order. It shows the Church of Rome already caring for the troubles of other churches in those early years.']],
 docs=[['Letter to the Corinthians', 'c. 96', 'A call to peace and order; one of the oldest Christian letters outside the New Testament.']])
P['papa-callixtus-1'] = dict(name='Pope Callixtus I', cat='A former slave who became pope, and a martyr · Saint', born='Rome',
 bio='In his youth he was a slave; he served a sentence in the mines and later came to lead the Church of Rome. The catacomb that bears his name is one of the most visited in Rome today.',
 secs=[['From slave to pope', 'While a slave of a Christian master he lost money in a banking venture and was sent to the mines of Sardinia. Once freed, Pope Zephyrinus put him in charge of the Christian cemetery on the Via Appia, known today as the Catacomb of St. Callixtus.'],
       ['A pope of mercy', 'He held that great sinners who repented should be welcomed back into the Church. This brought him into a deep dispute with Hippolytus, who took a hard line. He was martyred around 222.']],
 docs=[])
P['papa-silvester-1'] = dict(name='Pope Sylvester I', cat='Pope of the Council of Nicaea · Saint', born='Rome',
 bio='He became pope just after the Edict of Milan gave Christians their freedom. The first ecumenical council met in his time, at Nicaea (İznik) in 325.',
 secs=[['The first years of freedom', 'After three centuries of persecution, under Emperor Constantine the Church could at last live openly. During Sylvester’s papacy the Lateran Basilica and the first basilica over the tomb of St. Peter were built in Rome.'],
       ['His link to Turkey', 'Because of his age he could not go himself to the first ecumenical council, held at Nicaea (İznik) in 325; he sent two priests to represent him. The council declared that Christ is of the same substance as the Father and laid the foundation of the Creed still said today.']],
 docs=[])
P['papa-damasus-1'] = dict(name='Pope Damasus I', cat='Pope of the Vulgate · Saint', born='Rome',
 bio='He asked his secretary, St. Jerome, to make a new Latin translation of the Bible. Known as the Vulgate, it was the Western Church’s Bible for more than a thousand years.',
 secs=[['With Jerome', 'Damasus was troubled by the differences between the old Latin translations of the Bible. Around 382 he asked Jerome to revise the Gospels; in the years that followed Jerome translated the whole Bible.'],
       ['The tombs of the martyrs', 'He restored the martyrs’ tombs in the catacombs of Rome and had poems in their honour carved in marble; some of these inscriptions are still in place today.']],
 docs=[])
P['papa-celestinus-1'] = dict(name='Pope Celestine I', cat='Pope of the Council of Ephesus · Saint', born='Campania',
 bio='The Council of Ephesus, which honoured Mary as the “Mother of God”, met in his time. He also sent Ireland its first bishop.',
 secs=[['His link to Turkey', 'He sent his legates to the council held at Ephesus in 431. The council declared that it is right to call Mary “Theotokos”, Mother of God. The ruins of the Church of Mary, where the council met, can still be seen at Ephesus.'],
       ['Ireland', 'In 431 he sent Palladius as bishop to the Christians of Ireland. Tradition says St. Patrick went to the island soon afterwards to carry on this mission.']],
 docs=[])
P['papa-leo-1'] = dict(name='Pope Leo I (the Great)', cat='Doctor of the Church · Saint', born='Tuscany',
 bio='The first pope to be called “the Great”. His letter explaining that Jesus is true God and true man was read out at the Council of Chalcedon.',
 secs=[['The Tome of Leo', 'In 449 he wrote to Flavian, Patriarch of Constantinople, explaining clearly that Christ has two natures, divine and human, in one person. When the letter was read at the council held at Chalcedon (Kadıköy) in 451, the bishops are said to have cried out: “Peter has spoken through Leo.”'],
       ['Meeting Attila', 'When Attila the Hun invaded Italy in 452, Leo led the delegation that went out to meet him. Attila withdrew and Rome was spared. Three years later, when the Vandals sacked the city, Leo tried to talk them out of burning and slaughter.'],
       ['His link to Turkey', 'The Council of Chalcedon, which accepted Leo’s teaching, met in what is now the Kadıköy district of Istanbul. It gave the basic statement of faith about Christ that is still used today.']],
 docs=[['Letter to Flavian (the Tome)', '449', 'Two natures in Christ, one person. Read at the Council of Chalcedon.'],
       ['Sermons', '440-461', 'About a hundred sermons on Christmas, Easter and fasting.']])
P['papa-hormisdas'] = dict(name='Pope Hormisdas', cat='Pope of peace with the East · Saint', born='Frosinone',
 bio='He ended a thirty-five-year split between Rome and Constantinople with the statement of faith that bears his name.',
 secs=[['The Acacian schism', 'In 484 the bond between the Churches of Rome and Constantinople was broken. Hormisdas patiently worked to heal the rift, sending envoys to the East.'],
       ['His link to Turkey', 'In 519 Patriarch John II of Constantinople and Emperor Justin I signed the “Formula of Hormisdas”. It acknowledged that the Catholic faith had always been kept spotless in the Church of Rome. With it, Constantinople and Rome were reunited.']],
 docs=[['Formula of Hormisdas', '519', 'A statement of faith signed by the Eastern bishops, expressing their loyalty to the see of Peter.']])
P['papa-gregorius-1'] = dict(name='Pope Gregory I (the Great)', cat='Doctor of the Church · Saint', born='Rome',
 bio='While prefect of Rome he gave up everything to become a monk. As pope he called himself “the servant of the servants of God”, a title popes still use.',
 secs=[['His life', 'He came from a wealthy Roman family and became prefect of the city as a young man. When his father died he used his inheritance to found monasteries and became a monk himself. He was elected pope in years of plague and famine; he fed the poor and in practice governed the city.'],
       ['A mission to England', 'In 596 he sent the monk Augustine (Augustine of Canterbury) with a few companions to England. Through this mission Christianity spread among the Anglo-Saxons.'],
       ['His link to Turkey', 'Before becoming pope he lived in Constantinople for about six years as Rome’s envoy. There he came to know the Eastern Church and the imperial court at close hand.']],
 docs=[['Pastoral Rule', '590', 'How a shepherd of souls should live and teach; for centuries the handbook of bishops.'],
       ['Dialogues', '593', 'The lives of Italian saints, above all St. Benedict.']])
P['papa-martinus-1'] = dict(name='Pope Martin I', cat='Martyr pope tried in Constantinople · Saint', born='Todi',
 bio='He defended the two wills of Christ against the emperor; he was arrested, tried in Constantinople and died in exile. He is the last pope honoured as a martyr.',
 secs=[['The Lateran Synod', 'At the synod he called in Rome in 649 he openly declared that Christ has both a divine and a human will, despite Emperor Constans II’s decree forbidding the debate.'],
       ['His link to Turkey', 'In 653 the emperor’s soldiers arrested him in Rome and brought him to Constantinople. He was tried while ill, paraded through the streets in chains and exiled to Cherson in the Crimea. He died there in 655; his letters speak of hunger and loneliness.']],
 docs=[])
P['papa-agatho'] = dict(name='Pope Agatho', cat='Pope of the Third Council of Constantinople · Saint', born='Sicily',
 bio='His letter explaining that Christ has both a divine and a human will was read with joy at the council held in Constantinople.',
 secs=[['Two wills', 'At the time some taught that Christ had only one will. Agatho explained that because Christ is true God and true man he has two wills, and that his human will freely submits to the divine will.'],
       ['His link to Turkey', 'When his letter was read at the Sixth Ecumenical Council in Constantinople in 680-681, the council fathers cried out: “Peter has spoken through Agatho.”']],
 docs=[['Letter to the emperor', '680', 'The doctrinal letter, read at the council, explaining the two wills in Christ.']])
P['papa-sergius-1'] = dict(name='Pope Sergius I', cat='Son of a family from Antioch · Saint', born='Palermo',
 bio='He was the son of a Syrian family that had moved from Antioch to Sicily. He added to the Mass the “Lamb of God” (Agnus Dei) that is sung at every Mass today.',
 secs=[['The Lamb of God', 'He added to the Roman Mass the prayer “Lamb of God, you take away the sins of the world”, sung at the breaking of the bread. He also began the processions held on the feasts of Mary.'],
       ['His link to Turkey', 'In 692 he refused to sign some of the decisions of the Quinisext (Trullan) Synod in Constantinople. Emperor Justinian II sent an officer to arrest him; but the people and soldiers of Rome and Ravenna protected the pope, and the officer saved his life by hiding under the pope’s bed.']],
 docs=[])
P['papa-zacharias'] = dict(name='Pope Zachary', cat='A pope of Greek origin · Saint', born='Calabria',
 bio='He was among the last popes of Greek origin. His peaceful diplomacy protected Rome from Lombard attacks.',
 secs=[['An envoy of peace', 'He went in person to meet the Lombard king Liutprand and, without a battle, won back the cities that had been seized.'],
       ['Between two worlds', 'He translated Pope Gregory I’s “Dialogues” into Greek for the Christians of the East. In the West, the bond he formed with the Frankish king Pepin shaped the centuries that followed in Europe.']],
 docs=[])
P['papa-hadrianus-1'] = dict(name='Pope Adrian I', cat='Pope of the Second Council of Nicaea', born='Rome',
 bio='His twenty-three-year papacy is one of the longest since Peter. The Council of Nicaea that restored the veneration of holy icons met in his time.',
 secs=[['His link to Turkey', 'He sent his legates to the Seventh Ecumenical Council, held at Nicaea (İznik) in 787. The council put an end to the destruction of icons and taught that honour shown to an image passes to the person it depicts.'],
       ['Charlemagne', 'He was a close friend of the Frankish king Charlemagne. Grieved by his death, Charlemagne had a marble epitaph made for Adrian; it is in St. Peter’s Basilica today.']],
 docs=[])
P['papa-leo-3'] = dict(name='Pope Leo III', cat='The pope who crowned Charlemagne · Saint', born='Rome',
 bio='On Christmas night in the year 800, in St. Peter’s Basilica in Rome, he crowned Charlemagne emperor.',
 secs=[['Christmas 800', 'After he was attacked in Rome he took refuge with the Frankish king Charlemagne. On 25 December 800 he crowned Charlemagne “Emperor of the Romans”. This is seen as the beginning of the idea of the Holy Roman Empire, which would last for centuries in the West.']],
 docs=[])
P['papa-nicolaus-1'] = dict(name='Pope Nicholas I', cat='Nicholas “the Great” · Saint', born='Rome',
 bio='He defended the indissolubility of marriage against kings, and guided a whole people into Christianity with his long replies to the Bulgarians.',
 secs=[['Replies to the Bulgarians', 'In 866 the Bulgarian king Boris sent more than a hundred questions for his newly Christian people. Nicholas’s answers are full of gentle, practical advice on baptism, fasting, marriage and justice. In the same letter he writes that extracting confessions by torture is forbidden.'],
       ['His link to Turkey', 'He opposed the unjust removal of Ignatius, Patriarch of Constantinople. This dispute was one of the first steps in the long tensions between Rome and Constantinople.']],
 docs=[['Responsa ad consulta Bulgarorum', '866', '106 answers to the questions of the Bulgarians.']])
P['papa-formosus'] = dict(name='Pope Formosus', cat='Missionary to Bulgaria · the “Cadaver Synod”', born='Rome',
 bio='As a young man he was a missionary who preached the Gospel to the Bulgarians. After his death his body was dug up and put on trial; the event, known as the “Cadaver Synod”, stands for one of the darkest times in the Church’s history.',
 secs=[['In Bulgaria', 'In 866 Pope Nicholas I sent him as bishop to the newly Christian Bulgarians. King Boris loved him so much that he wanted him to become archbishop of Bulgaria.'],
       ['The Cadaver Synod', 'In 897 his successor Stephen VI, out of political spite, had Formosus’s body taken from the grave, dressed in papal vestments, seated on a throne and put on trial. The people were outraged by the scandal; Stephen was deposed that same year. Later popes restored Formosus’s good name.']],
 docs=[])
P['papa-silvester-2'] = dict(name='Pope Sylvester II', cat='The scholar pope · the pope of the year 1000', born='Auvergne',
 bio='He was a mathematician, astronomer and teacher. He was one of those who brought Arabic numerals and the abacus to Western Europe, and he entered the year 1000 as pope.',
 secs=[['Gerbert', 'His real name was Gerbert. As a young man he studied mathematics and astronomy in Spain, in monasteries where the learning of al-Andalus flowed in. At his school in Reims he used celestial spheres and the abacus in his lessons.'],
       ['The first French pope', 'Elected in 999, he was the first French pope. By setting up the Church structures of Hungary and Poland, he helped bring Central Europe into the Christian world.']],
 docs=[])
P['papa-leo-9'] = dict(name='Pope Leo IX', cat='A reforming pope · Saint', born='Egisheim, Alsace',
 bio='He travelled the length of Europe to free the Church from bribery and worldliness. The end of his papacy was overshadowed by the split between East and West in 1054.',
 secs=[['A pope on the road', 'He spent most of his five-year papacy travelling, holding synods in Italy, France and Germany. He began a determined fight against the buying and selling of Church offices.'],
       ['His link to Turkey', 'In 1054 he sent envoys to Constantinople. After Leo died in April, on 16 July 1054 Cardinal Humbert laid the bull of excommunication on the altar of Hagia Sophia. The event became the symbol of the split between East and West; the mutual excommunications were lifted in 1965 by Pope Paul VI and Patriarch Athenagoras.']],
 docs=[])
P['papa-gregorius-7'] = dict(name='Pope Gregory VII', cat='The reforming pope · Saint', born='Tuscany',
 bio='He fought to make the Church independent of kings and money. Emperor Henry IV waited in the snow at Canossa for his forgiveness.',
 secs=[['The Gregorian reform', 'In his day Church offices were often sold for money and bishops were appointed by kings. Gregory opposed this and firmly upheld the celibate life of priests.'],
       ['Canossa', 'He clashed with Emperor Henry IV over the right to appoint bishops, and cut him off from the Church. In the winter of 1077 the emperor waited for three days as a penitent outside the castle of Canossa in northern Italy, and was forgiven.'],
       ['Death in exile', 'The conflict later flared up again. Gregory had to leave Rome and died in Salerno. His last words are said to have been: “I have loved justice and hated iniquity; therefore I die in exile.”']],
 docs=[['Dictatus Papae', '1075', '27 short statements on the authority of the pope.']])
P['papa-urbanus-2'] = dict(name='Pope Urban II', cat='Blessed', born='Châtillon-sur-Marne',
 bio='His speech at Clermont in 1095 launched the First Crusade.',
 secs=[['Clermont', 'The Byzantine emperor Alexios I Komnenos asked the West for help against the Seljuk advance in Anatolia. In 1095 at Clermont, Urban called on Western Christians to help the Christians of the East and to go to Jerusalem.'],
       ['His link to Turkey', 'The crusaders besieged Nicaea (İznik) in 1097 and crossed Anatolia to reach Antioch. The crusades left deep marks on the lands of today’s Turkey; today the Church also openly acknowledges the dark sides of that time.']],
 docs=[])
